//
// specificity(selector) -> [a, b, c]
//   a = IDs
//   b = classes + attributes + pseudo-classes
//   c = type selectors + pseudo-elements
//
// :not(), :is(), :has() take the specificity of their most specific argument.
// :where() always contributes zero. Combinators (descendant, >, +, ~)
// contribute nothing.

const LEGACY_PSEUDO_ELEMENTS = new Set([
  'before',
  'after',
  'first-line',
  'first-letter',
