const LEVELING_PSEUDO_CLASSES = new Set(['not', 'is', 'has', 'matches']);

const IDENT = /[-\w\u00A0-\uFFFF]|\\./;

/**
 * Split a selector into compound selectors, discarding combinators
 * (combinators contribute nothing to specificity).
 * Handles quotes and nested brackets/parens.
 */
function splitCompounds(selector) {
  const compounds = [];
  let current = '';
  let parenDepth = 0;
  let bracketDepth = 0;
  let quote = null;

  for (let i = 0; i < selector.length; i++) {
    const ch = selector[i];

    if (quote) {
      current += ch;
      if (ch === quote && selector[i - 1] !== '\\') quote = null;
      continue;
    }

    if ((ch === '"' || ch === "'") && bracketDepth > 0) {
      quote = ch;
      current += ch;
      continue;
    }

    if (ch === '[') bracketDepth++;
    if (ch === ']') bracketDepth--;
    if (ch === '(' && bracketDepth === 0) parenDepth++;
    if (ch === ')' && bracketDepth === 0) parenDepth--;

    if (
      parenDepth === 0 &&
      bracketDepth === 0 &&
      (ch === '>' || ch === '+' || ch === '~')
    ) {
      if (current.trim()) compounds.push(current.trim());
      current = '';
      continue;
    }

    if (
      parenDepth === 0 &&
      bracketDepth === 0 &&
      /\s/.test(ch)
    ) {
      // Whitespace may be a descendant combinator; flush any complete compound
      // but tolerate leading/trailing space around explicit combinators.
      if (current.trim()) compounds.push(current.trim());
      current = '';
      continue;
    }

    current += ch;
