function addTriple(a, b) {
  return [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
}

function compareTriple(a, b) {
  return a[0] - b[0] || a[1] - b[1] || a[2] - b[2];
}

/** Specificity contributed by a single compound selector. */
function compoundSpecificity(compound) {
  let result = [0, 0, 0];
  let i = 0;

  while (i < compound.length) {
    const ch = compound[i];

