          let best = [0, 0, 0];
          for (const part of splitSelectorList(args)) {
            const s = specificity(part);
            if (compareTriple(s, best) > 0) best = s;
          }
          result = addTriple(result, best);
        } else if (args !== null && name === 'where') {
          // :where() contributes zero.
        } else {
          result[1]++; // ordinary pseudo-class (:hover, :checked, ...)
        }
      }
    } else if (IDENT.test(ch)) {
      // Type selector
      [, i] = readIdent(compound, i);
      result[2]++;
    } else {
      i++; // unknown character; skip defensively
    }
  }

  return result;
