/**
 * Compute the specificity triple [a, b, c] of a CSS selector.
 *
 * @param {string} selector - e.g. "#main .item:hover"
 * @returns {[number, number, number]}
 */
export function specificity(selector) {
  const compounds = splitCompounds(String(selector));
  let result = [0, 0, 0];
  for (const compound of compounds) {
    result = addTriple(result, compoundSpecificity(compound));
  }
  return result;
}

/**
 * Sort cascade rules ({selector, sourceOrder}) in ascending cascade order:
 * primary key is specificity, secondary key is source order — later wins.
 *
 * @param {{selector: string, sourceOrder: number}[]} rules
 * @returns {Array} a new sorted array
 */
export function cascadeSort(rules) {
  return [...rules].sort((x, y) => {
    const bySpec = compareTriple(specificity(x.selector), specificity(y.selector));
    if (bySpec !== 0) return bySpec;
    return x.sourceOrder - y.sourceOrder;
  });
}
