result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/specificity/test/specificity.test.js", "content": "import { describe, it, expect } from 'vitest';
import { specificity, cascadeSort } from '../src/index.js';

describe('specificity()', () => {
  // selector -> exact [a, b, c] triple
  const cases = [
    ['*', [0, 0, 0]],
    ['li', [0, 0, 1]],
    ['ul li', [0, 0, 2]],
    ['ul > li', [0, 0, 2]], // child combinator contributes nothing
    ['h1 ~ p', [0, 0, 2]], // sibling combinator contributes nothing
    ['h1 + p', [0, 0, 2]], // adjacent sibling contributes nothing
    ['nav ul li.active a', [0, 1, 4]], // 4 elements + 1 class
    ['.item:hover', [0, 2, 0]],
    ['#main .item:hover', [1, 2, 0]],
    ['#a#b.c', [2, 1, 0]],
    ['a[href^="https"]', [0, 1, 1]], // attribute w/ value + element
    ['input[type="checkbox"]:checked', [0, 2, 1]],
    ['[data-x="foo bar"]', [0, 1, 0]], // spaces inside attribute value
    [':is(#a, .b)', [1, 0, 0]], // most specific argument wins
    [':is(#a, .b) span', [1, 0, 1]],
    [':where(#a)', [0, 0, 0]], // :where always contributes zero
    [':where(#a) > p.highlight', [0, 1, 2]],
    ['div:not(.x)', [0, 1, 1]],
    ['li:not(.a):not(.b)', [0, 3, 1]], // :not levels up like :is
    ['li::marker', [0, 0, 2]], // pseudo-element
    ['a::after', [0, 0, 2]],
    ['p:before', [0, 0, 2]], // legacy single-colon pseudo-element
    ['.menu li a span.icon', [0, 2, 4]],
  ];

  for (const [selector, expected] of cases) {
    it(`"${selector}" -> [${expected.join(', ')}]`, () => {
      expect(specificity(selector)).toEqual(expected);
    });
  }
});

describe('cascadeSort()', () => {
  const rules = (pairs) => pairs.map(([selector, sourceOrder]) => ({ selector, sourceOrder }));

  it('orders by specificity first: higher specificity wins regardless of order', () => {
    const sorted = cascadeSort(
      rules([
        ['#id', 0],
        ['.cls', 1], // later in source, but lower specificity
      ])
    );
    expect(sorted.map((r) => r.selector)).toEqual(['.cls', '#id']);
  });

  it('breaks specificity ties by source order: later wins', () => {
    const sorted = cascadeSort(
      rules([
        ['.first', 10],
        ['.second', 20],
        ['.third', 30],
      ])
    );
    expect(sorted.map((r) => r.sourceOrder)).toEqual([10, 20, 30]);
  });

  it('tie-breaks by source order even across different equal-specificity selectors', () => {
    const sorted = cascadeSort(
      rules([
        ['div', 5],
        ['section p', 2], // same specificity [0,0,1] vs [0,0,2]? no — use true tie:
      ])
    );
    // div = [0,0,1]; make an actual tie with another [0,0,1]
    const tied = cascadeSort(
      rules([
        ['div', 7],
        ['span', 3],
        ['em', 9],
      ])
    );
    expect(tied.map((r) => r.sourceOrder)).toEqual([3, 7, 9]);
    void sorted;
  });

  it('does not mutate the input array', () => {
    const input = rules([
      ['.a', 1],
      ['#b', 0],
    ]);
    const copy = [...input];
    cascadeSort(input);
    expect(input).toEqual(copy);
  });

  it('sorts a realistic mixed cascade', () => {
    const sorted = cascadeSort(
      rules([
        ['nav ul li.active a', 100], // [0,1,4]
        ['*', 200], // [0,0,0]
        ['a', 300], // [0,0,1]
        ['#main .item:hover', 50], // [1,2,0]
        ['li::marker', 400], // [0,0,2]
      ])
    );
    expect(sorted.map((r) => r.selector)).toEqual([
      '*',
      'a',
      'li::marker',
      'nav ul li.active a',
      '#main .item:hover',
    ]);
  });
});
"})
